import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def masks(ctx):
    inputs = torch.rand(16, generator=ctx.rng.torch)
    targets = (inputs.reshape(1, 4, 4) > 0.5).float()
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(targets)}
dataset = synth.Spec("combo-loss-masks", generator=masks, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("regression", split="train", input_field="inputs", target_field="targets", preserve_shape=True)
class Segmenter(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=16, out_features=16)
    def forward(self, inputs):
        logits = self.network(inputs.reshape(inputs.shape[0], -1))
        return torch.sigmoid(logits).reshape(-1, 1, 4, 4)
trainer = Trainer(Segmenter(), train, recipe="regression", recipe_config={"loss": "combo-loss", "loss_kwargs": {"alpha": 0.5, "beta": 0.5}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
